1	/// schema.rs — JSON Schema validation layer (INV-4).
2	///
3	/// Every dispatched call validates its `params` against the tool's schema
4	/// before the handler runs. Schemas live in `schemas/*.json` and are embedded
5	/// at compile time via `include_str!`, so the validator has no runtime IO and
6	/// can't be tampered with at runtime.
7	///
8	/// On validation failure the caller should return JSON-RPC error -32602
9	/// (Invalid params) per the JSON-RPC 2.0 spec.
10	use anyhow::{anyhow, Result};
11	use jsonschema::JSONSchema;
12	use serde_json::Value;
13	use std::collections::HashMap;
14	use std::sync::OnceLock;
15	
16	/// SemVer of the schema catalogue. Bumped on any schema change.
17	/// Major bump = breaking change (Controller must re-pin).
18	/// Minor bump = additive (new tool, new optional field).
19	pub const SCHEMA_VERSION: &str = "1.0.0";
20	
21	/// Source of each schema JSON, embedded at compile time.
22	/// Add a new tool by adding both a schema JSON file under `schemas/`
23	/// AND a line here, then exposing the method in `tools::mod` and `server::dispatch`.
24	const SCHEMA_SOURCES: &[(&str, &str)] = &[
25	    ("system.status",  include_str!("../schemas/system.status.json")),
26	    ("system.uptime",  include_str!("../schemas/system.uptime.json")),
27	    ("system.cpu",     include_str!("../schemas/system.cpu.json")),
28	    ("system.memory",  include_str!("../schemas/system.memory.json")),
29	    ("system.disk",    include_str!("../schemas/system.disk.json")),
30	    ("process.list",   include_str!("../schemas/process.list.json")),
31	    ("process.inspect", include_str!("../schemas/process.inspect.json")),
32	    ("fs.read",        include_str!("../schemas/fs.read.json")),
33	    ("fs.list",        include_str!("../schemas/fs.list.json")),
34	    ("fs.stat",        include_str!("../schemas/fs.stat.json")),
35	    ("fs.write",       include_str!("../schemas/fs.write.json")),
36	    ("fs.delete",      include_str!("../schemas/fs.delete.json")),
37	    ("service.start",  include_str!("../schemas/service.start.json")),
38	    ("service.stop",   include_str!("../schemas/service.stop.json")),
39	    ("service.restart", include_str!("../schemas/service.restart.json")),
40	    ("service.logs",   include_str!("../schemas/service.logs.json")),
41	    ("network.status", include_str!("../schemas/network.status.json")),
42	    ("network.dns.read", include_str!("../schemas/network.dns.read.json")),
43	    ("package.query",  include_str!("../schemas/package.query.json")),
44	    ("package.install", include_str!("../schemas/package.install.json")),
45	    ("package.remove", include_str!("../schemas/package.remove.json")),
46	    ("package.upgrade", include_str!("../schemas/package.upgrade.json")),
47	];
