49	/// `tools/list` has no schema — it's the discovery endpoint, accepts any params.
50	const UNCHECKED_METHODS: &[&str] = &["tools/list"];
51	
52	struct Registry {
53	    schemas: HashMap<String, JSONSchema>,
54	    /// Kept around so JSON Schema's borrowed references remain valid for the
55	    /// lifetime of the registry.
56	    sources: HashMap<String, Value>,
57	}
58	
59	fn registry() -> &'static Registry {
60	    static REGISTRY: OnceLock<Registry> = OnceLock::new();
61	    REGISTRY.get_or_init(|| {
62	        let mut sources = HashMap::new();
63	        for (name, src) in SCHEMA_SOURCES {
64	            let parsed: Value = serde_json::from_str(src)
65	                .unwrap_or_else(|e| panic!("schemas/{}.json is not valid JSON: {}", name, e));
66	            sources.insert(name.to_string(), parsed);
67	        }
68	        let mut schemas = HashMap::new();
69	        for (name, parsed) in &sources {
70	            let compiled = JSONSchema::compile(parsed)
71	                .unwrap_or_else(|e| panic!("schemas/{}.json failed to compile: {}", name, e));
72	            schemas.insert(name.clone(), compiled);
73	        }
74	        Registry { schemas, sources }
75	    })
76	}
