78	/// Validate `params` against the schema for `method`.
79	///
80	/// Returns `Err` with a human-readable message if the schema doesn't exist or
81	/// validation fails. Methods in `UNCHECKED_METHODS` return `Ok` regardless.
82	///
83	/// IMPORTANT: methods that are NOT in the schema catalogue also return `Err`.
84	/// The dispatcher should check for "unknown method" BEFORE calling validate,
85	/// so that a real "method not found" returns -32601 instead of -32602.
86	pub fn validate(method: &str, params: &Value) -> Result<()> {
87	    if UNCHECKED_METHODS.contains(&method) {
88	        return Ok(());
89	    }
90	    let reg = registry();
91	    let schema = reg.schemas.get(method)
92	        .ok_or_else(|| anyhow!("No schema registered for method '{}'", method))?;
93	    if let Err(errors) = schema.validate(params) {
94	        let msgs: Vec<String> = errors.map(|e| format!("{} at {}", e, e.instance_path)).collect();
95	        return Err(anyhow!("{}", msgs.join("; ")));
96	    }
97	    Ok(())
98	}
99	
100	/// Returns the raw schema JSON for `method`, or `None` if not registered.
101	/// Used by `tools::list_all()` to embed each tool's schema in the catalogue
102	/// response so the Controller can validate Intent Objects against it.
103	pub fn schema_json(method: &str) -> Option<&'static Value> {
104	    // Safety: registry() returns a 'static reference; the inner Value lives
105	    // as long as the registry, which is 'static.
106	    registry().sources.get(method)
107	}
108	
109	/// Iterate over all registered method names. Used to assert that every
110	/// dispatchable method has a schema.
111	pub fn registered_methods() -> impl Iterator<Item = &'static str> {
112	    SCHEMA_SOURCES.iter().map(|(name, _)| *name)
113	}
