71	/// Returns the complete MCP tool catalogue for discovery (`tools/list`).
72	/// Each tool entry includes its real JSON Schema (from `schemas/<name>.json`),
73	/// so the Controller validates Intent Objects against the same schema mcpd
74	/// uses to gate dispatch (INV-4).
75	pub fn list_all() -> anyhow::Result<Value> {
76	    let tools: Vec<Value> = TOOLS.iter().map(|t| {
77	        let params_schema = schema::schema_json(t.name).cloned().unwrap_or_else(|| json!({}));
78	        json!({
79	            "name": t.name,
80	            "description": t.description,
81	            "category": t.category,
82	            "tier": t.tier,
83	            "read_only": t.read_only,
84	            "params_schema": params_schema,
85	        })
86	    }).collect();
87	
88	    Ok(json!({
89	        "schema_version": schema::SCHEMA_VERSION,
90	        "tools": tools,
91	    }))
92	}
