  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "fs.write",
  "description": "Write UTF-8 content to a file. Tier 1 (execute directly) when path is under $HOME AND not in a sensitive subdir (.ssh, .aws, .gnupg, .config/secrets). Otherwise Tier 3: returns requires_cow_approval and Phase 3's COW commit pipe carries the write through to the kernel.",
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096,
      "description": "Absolute path of the file to write."
    },
    "content": {
      "type": "string",
      "description": "UTF-8 content to write. Binary writes land in Phase 5."
    },
    "mode": {
      "type": "integer",
      "minimum": 0,
      "maximum": 4095,
      "description": "POSIX permissions (octal as decimal). Defaults to 0o644 (420) when omitted."
    }
  },
  "required": ["path", "content"],
  "additionalProperties": false
}

